/* Additive, original CEE-style practice. These are not verified past-paper questions.
 * Scientific background references are further reading, not question provenance.
 * Existing notes and question-bank entries are never replaced.
 */
(() => {
  const references = {
    physics: ['College Physics 2e — further reading', 'https://openstax.org/details/books/college-physics-2e'],
    chemistry: ['Chemistry 2e — further reading', 'https://openstax.org/details/books/chemistry-2e'],
    biology: ['Biology 2e — further reading', 'https://openstax.org/details/books/biology-2e'],
    mathematics: ['Precalculus 2e — further reading', 'https://openstax.org/details/books/precalculus-2e']
  };
  window.CEE_ADVANCED_CONTENT = {};
  function add(path, note, ...items) {
    const [subject, category, key] = path.split('/');
    const chapter = window.eduPeakData?.[subject]?.[category]?.[key];
    if (!chapter) throw new Error('Unknown chapter: ' + path);
    const questions = items.map(([question, options, correct, explanation], i) => ({
      id: 'CF26-' + path.replaceAll('/', '-') + '-' + (i + 1), subject: subject[0].toUpperCase() + subject.slice(1),
      chapter: chapter.name, difficulty: i === 0 ? 'M' : 'H', question, options, correct, explanation,
      provenance: 'Original CEE-style practice; not a verified past-paper question'
    }));
    window.CEE_ADVANCED_CONTENT[path] = { note, questions, reference: references[subject] };
    window.EDUPEAK_QUESTION_BANK[subject] ||= [];
    window.EDUPEAK_QUESTION_BANK[subject].push(...questions);
  }
  add('physics/mechanics/units', 'For products and powers, add fractional uncertainties multiplied by the absolute powers. Dimensional consistency is necessary but cannot determine dimensionless constants. Resolve vectors into components before combining them; add magnitudes only when their directions permit it.',
    ['Density is calculated as 4m/(pi d²L). Independent maximum errors in m, d and L are 1%, 2% and 1%. The maximum percentage error in density is:', ['4%', '6%', '8%', '2%'], 1, 'Maximum fractional error = 1 + 2(2) + 1 = 6%. The diameter is squared, so its contribution doubles.'],
    ['A = 3i + 4j and B = 4i - 3j. The magnitude of A + B is:', ['5', '10', '5√2', '7'], 2, 'A+B=7i+j. Its magnitude is √(49+1)=√50=5√2. A·B=0, so the vectors are perpendicular.']);
  add('physics/mechanics/kinematics', 'A velocity-time graph gives signed displacement by its area; distance requires areas to be counted positively. Constant-acceleration equations apply separately to each phase of a journey. Locate changes of direction by setting velocity equal to zero before calculating distance.',
    ['A particle starts at 20 m/s and brakes uniformly at 4 m/s². Its stopping distance is:', ['25 m', '50 m', '80 m', '100 m'], 1, 'Use v²=u²+2as. With v=0, s=400/8=50 m. Stopping time is 5 s.'],
    ['A particle has v(t)=6t-3t² m/s for 0≤t≤3 s. Total distance travelled is:', ['0 m', '9 m', '8 m', '16 m'], 2, 'Velocity changes sign at t=2. Position change is x=3t²-t³. From 0 to 2: 4 m; from 2 to 3: -4 m. Distance=4+4=8 m.']);
  add('physics/mechanics/projectile', 'Treat horizontal and vertical motions independently for an ideal projectile. The familiar range formula assumes equal launch and landing heights. In circular motion acceleration points towards the centre even when speed is constant; the required radial force is a net force, not an additional interaction.',
    ['A projectile is launched at 20 m/s at 30° on level ground. With g=10 m/s², its maximum height is:', ['5 m', '10 m', '15 m', '20 m'], 0, 'Vertical initial speed=20 sin30°=10 m/s. H=u_y²/(2g)=100/20=5 m.'],
    ['A stone moves in a vertical circle of radius 2 m on a light string. Minimum speed at the bottom for a complete taut-string circle is (g=10 m/s²):', ['√20 m/s', '√40 m/s', '10 m/s', '20 m/s'], 2, 'At the limiting top position v_top²=gr. Energy conservation gives v_bottom²=v_top²+4gr=5gr=100. Thus v_bottom=10 m/s.']);
  add('physics/mechanics/newton', 'Draw a separate free-body diagram for each body. Static friction adjusts up to its limiting value; kinetic friction applies after sliding begins. Tension is equal along a massless string over an ideal pulley, but is not generally equal to either hanging weight.',
    ['A 5 kg block slides on a horizontal surface with coefficient of kinetic friction 0.2. A horizontal 30 N force pulls it. For g=10 m/s², acceleration is:', ['2 m/s²', '4 m/s²', '6 m/s²', '8 m/s²'], 1, 'Normal force=50 N; friction=10 N. Net horizontal force=20 N; a=20/5=4 m/s².'],
    ['Masses 3 kg and 2 kg hang over an ideal pulley. With g=10 m/s², the string tension is:', ['20 N', '24 N', '25 N', '30 N'], 1, 'a=(3-2)g/(3+2)=2 m/s². For the rising 2 kg mass, T-20=2×2; T=24 N.']);
  add('physics/mechanics/work', 'The work-energy theorem uses net work, including friction. Mechanical energy is conserved only when nonconservative work is absent or explicitly accounted for. Instantaneous power is the scalar product F·v; a force perpendicular to velocity does no work.',
    ['A 2 kg body accelerates from 3 m/s to 7 m/s. Net work done is:', ['20 J', '40 J', '49 J', '58 J'], 1, 'Net work=ΔK=(1/2)×2×(49-9)=40 J.'],
    ['A 2 kg block starts from rest and compresses a horizontal spring by 0.20 m, after a 10 N constant force acts over that same 0.20 m. If k=50 N/m and there is no friction, its speed at that position is:', ['1 m/s', '√2 m/s', '2 m/s', '0 m/s'], 0, 'Applied work=10×0.20=2 J. Spring energy=(1/2)×50×0.20²=1 J. Remaining K=1 J=(1/2)×2×v², so v=1 m/s.']);
  add('physics/mechanics/rotational', 'Choose an axis before calculating moment of inertia. Apply the parallel-axis theorem only with the displacement from a parallel axis through the centre of mass. Rolling without slipping requires v=ωR and includes both translational and rotational kinetic energy.',
    ['A solid disc of mass 2 kg and radius 0.5 m rotates at 4 rad/s. Its rotational kinetic energy is:', ['1 J', '2 J', '4 J', '8 J'], 1, 'I=MR²/2=0.25 kg m². K=Iω²/2=0.25×16/2=2 J.'],
    ['A uniform solid cylinder rolls without slipping from rest through a vertical drop of 1.5 m. With g=10 m/s², its final speed is:', ['√10 m/s', '√15 m/s', '√20 m/s', '√30 m/s'], 2, 'mgh=(1/2)mv²+(1/2)(mR²/2)(v/R)²=(3/4)mv². Hence v²=4gh/3=20.']);
  add('physics/mechanics/gravitation', 'Potential is negative when zero is chosen at infinity, while gravitational field is a vector. Orbital speed varies as r^(-1/2) and orbital period as r^(3/2). Escape speed assumes no further propulsion and neglects atmosphere and rotation.',
    ['At a height equal to Earth’s radius above its surface, gravitational acceleration is:', ['g/2', 'g/4', 'g/8', 'g'], 1, 'Distance from the centre is 2R. Since g varies as 1/r², g_new=g/4.'],
    ['Two satellites have circular orbital radii r and 4r around the same planet. The ratio of their orbital periods T(4r)/T(r) is:', ['2', '4', '8', '16'], 2, 'Kepler’s law gives T∝r^(3/2). The ratio is 4^(3/2)=8.']);
  add('physics/thermodynamics/solids', 'Pressure differences in a static liquid depend on vertical depth, not vessel shape. Continuity conserves volume flow for incompressible steady flow. Bernoulli’s equation assumes negligible viscosity and is applied along a streamline; check elevation as well as speed.',
    ['Water flows through a pipe whose radius narrows from 4 cm to 2 cm. If the initial speed is 1 m/s, the final speed is:', ['2 m/s', '4 m/s', '8 m/s', '16 m/s'], 1, 'A₁v₁=A₂v₂ and area∝r². Speed rises by (4/2)²=4, giving 4 m/s.'],
    ['In a horizontal ideal water pipe, speed increases from 2 m/s to 6 m/s. For density 1000 kg/m³, the pressure decrease is:', ['8000 Pa', '16000 Pa', '24000 Pa', '32000 Pa'], 1, 'P₁-P₂=(ρ/2)(v₂²-v₁²)=500×(36-4)=16000 Pa.']);
  add('physics/thermodynamics/thermal', 'Separate sensible heat from latent heat in calorimetry. During a phase change at fixed pressure, energy changes without a temperature rise. Thermal expansion coefficients are approximate over small temperature ranges; for isotropic solids, volume expansion coefficient is about three times the linear coefficient.',
    ['How much heat raises 0.5 kg water from 20°C to 40°C? Use c=4200 J kg⁻¹ K⁻¹.', ['21 kJ', '42 kJ', '84 kJ', '420 kJ'], 1, 'Q=mcΔT=0.5×4200×20=42000 J=42 kJ.'],
    ['In an insulated vessel, 0.10 kg ice at 0°C is added to 0.20 kg water at 50°C. Use L_f=336000 J/kg and c=4200 J kg⁻¹ K⁻¹. Final temperature is:', ['0°C', '6.67°C', '10°C', '16.67°C'], 1, 'Warm water can release 42000 J cooling to 0°C. Melting needs 33600 J; remaining 8400 J heats 0.30 kg water. T=8400/(0.30×4200)=6.67°C.']);
  add('physics/thermodynamics/thermodynamics', 'With work done by the gas positive, ΔU=Q-W. For an ideal gas internal energy depends on temperature alone. A Carnot efficiency uses absolute temperatures; real heat engines operate below this reversible upper bound.',
    ['A gas absorbs 500 J and does 200 J of work. The change in its internal energy is:', ['-300 J', '300 J', '500 J', '700 J'], 1, 'ΔU=Q-W=500-200=300 J.'],
    ['A Carnot engine receives 1200 J per cycle from a 600 K reservoir and rejects heat to 300 K. Work per cycle is:', ['300 J', '600 J', '900 J', '1200 J'], 1, 'η=1-T_c/T_h=1-300/600=0.5. W=ηQ_h=600 J.']);
  add('physics/thermodynamics/kinetic', 'Use kelvin in kinetic-theory relations. Root-mean-square speed depends on temperature and molar mass, not directly on pressure. At the same temperature different ideal gases have equal mean translational kinetic energy per molecule but different characteristic speeds.',
    ['The absolute temperature of an ideal gas rises from 300 K to 1200 K. Its rms molecular speed becomes:', ['Half', 'Double', 'Four times', 'Unchanged'], 1, 'v_rms∝√T, so the ratio is √(1200/300)=2.'],
    ['At equal temperature, the ratio v_rms(H₂)/v_rms(O₂) is:', ['2', '4', '8', '16'], 1, 'v_rms∝1/√M. The ratio is √(32/2)=4.']);
  add('physics/waves/shm', 'In SHM acceleration is proportional to displacement and directed towards equilibrium. Speed is greatest at equilibrium and zero at the extremes. Mechanical energy stays constant in an ideal oscillator, with kinetic and potential energy exchanging throughout a cycle.',
    ['A spring with k=200 N/m carries a 2 kg mass. Its angular frequency is:', ['5 rad/s', '10 rad/s', '20 rad/s', '100 rad/s'], 1, 'ω=√(k/m)=√100=10 rad/s.'],
    ['An SHM oscillator has amplitude 0.10 m and angular frequency 20 rad/s. Its speed at displacement 0.06 m is:', ['0.8 m/s', '1.2 m/s', '1.6 m/s', '2.0 m/s'], 2, 'v=ω√(A²-x²)=20√(0.0100-0.0036)=20×0.08=1.6 m/s.']);
  add('physics/waves/sound', 'Distinguish particle motion from wave propagation. Standing-wave boundary conditions determine which harmonics are permitted. In Doppler problems establish whether source and observer approach or separate before choosing signs; the speed of sound is measured relative to the medium.',
    ['A string fixed at both ends has length 1 m and wave speed 200 m/s. Fundamental frequency is:', ['50 Hz', '100 Hz', '200 Hz', '400 Hz'], 1, 'For the fundamental, λ=2L=2 m; f=v/λ=100 Hz.'],
    ['A 600 Hz source moves towards a stationary observer at 30 m/s in still air. Speed of sound is 330 m/s. Observed frequency is:', ['550 Hz', '600 Hz', '660 Hz', '720 Hz'], 2, 'For an approaching source f′=fv/(v-v_s)=600×330/300=660 Hz.']);
  add('physics/electromagnetism/electrostatics', 'Superpose electric fields as vectors. For a charge in equilibrium both force components must vanish; a zero potential does not imply zero field. Gauss’s law always holds, but only high symmetry lets the field be taken outside a Gaussian-surface integral.',
    ['Two positive charges of 2 μC each are 0.30 m apart in vacuum. With k=9×10⁹ N m²/C², their repulsive force is:', ['0.04 N', '0.4 N', '4 N', '40 N'], 1, 'F=kq₁q₂/r²=9×10⁹×4×10⁻¹²/0.09=0.4 N.'],
    ['Charges +q and +4q are separated by d. Between them, the zero-field point is at what distance from +q?', ['d/2', 'd/3', '2d/3', 'd/4'], 1, 'Set kq/x²=k(4q)/(d-x)². Thus d-x=2x and x=d/3.']);
  add('physics/electromagnetism/potential', 'Capacitance is a geometric property for a linear capacitor. With a battery connected, voltage is fixed; after isolation, charge is fixed. Inserting a dielectric therefore changes stored energy differently in these two cases.',
    ['Capacitors 3 μF and 6 μF are in series. Equivalent capacitance is:', ['2 μF', '3 μF', '4.5 μF', '9 μF'], 0, '1/C=1/3+1/6=1/2, so C=2 μF.'],
    ['An isolated charged capacitor has stored energy U. A dielectric of constant 4 fills the gap. New stored energy is:', ['4U', '2U', 'U/2', 'U/4'], 3, 'Isolation keeps Q constant. C becomes 4C and U=Q²/(2C) becomes U/4.']);
  add('physics/electromagnetism/current', 'Use junction rules for charge conservation and loop rules for energy conservation. Terminal voltage differs from emf when current flows through internal resistance. Combining cells or resistors requires attention to how they are connected, not simply to their count.',
    ['Resistors 6 Ω and 3 Ω are connected in parallel across 12 V. Total current is:', ['2 A', '4 A', '6 A', '9 A'], 2, 'Equivalent resistance=6×3/(6+3)=2 Ω. I=12/2=6 A.'],
    ['A cell has emf 12 V and internal resistance 1 Ω. For maximum power delivered to an adjustable external resistor, that power is:', ['12 W', '24 W', '36 W', '144 W'], 2, 'Maximum load power occurs at R=r=1 Ω. I=12/(1+1)=6 A. P=I²R=36 W.']);
  add('physics/electromagnetism/magnetism', 'A magnetic force changes the direction but not the kinetic energy of a freely moving charge. Use only the velocity component perpendicular to the field for the circular radius. A parallel component produces a helical path rather than changing the gyroradius.',
    ['A charge of 2 μC moves at 10⁴ m/s perpendicular to a 0.5 T field. Force magnitude is:', ['0.001 N', '0.01 N', '0.1 N', '1 N'], 1, 'F=qvB=2×10⁻⁶×10⁴×0.5=0.01 N.'],
    ['A proton and an alpha particle enter the same uniform magnetic field normally with equal kinetic energies. The ratio r_alpha/r_proton is approximately:', ['1/2', '1', '2', '4'], 1, 'r=√(2mK)/(qB). Alpha mass≈4m_p and charge=2e, so the ratio is √4/2=1.']);
  add('physics/electromagnetism/emi', 'Induced emf depends on the rate of change of flux linkage, not on flux alone. Lenz’s law gives the direction that opposes the change. For a moving rod identify the component of velocity perpendicular to both the rod and the magnetic field.',
    ['Flux through each turn of a 100-turn coil changes uniformly from 0.02 Wb to 0.05 Wb in 0.10 s. Induced emf magnitude is:', ['3 V', '30 V', '50 V', '300 V'], 1, '|ε|=N|ΔΦ|/Δt=100×0.03/0.10=30 V.'],
    ['A 0.5 m rod moves at 4 m/s perpendicular to itself and to a 2 T field, closing an ideal rail circuit of total resistance 2 Ω. Magnetic drag force is:', ['1 N', '2 N', '4 N', '8 N'], 1, 'ε=Blv=4 V, I=ε/R=2 A. Drag F=BIl=2×2×0.5=2 N. Its mechanical power Fv=8 W equals I²R.']);
  add('physics/electromagnetism/ac', 'Use rms values in average AC power calculations. Inductive and capacitive reactances subtract in a series RLC circuit; resistance does not. At series resonance the impedance is R and the power factor is one, although reactive voltages can be large.',
    ['A sinusoidal current has peak value 5√2 A. Its rms value is:', ['2.5 A', '5 A', '5√2 A', '10 A'], 1, 'I_rms=I_peak/√2=5 A.'],
    ['A series RLC circuit has R=30 Ω, X_L=70 Ω and X_C=30 Ω, supplied at 100 V rms. Average power is:', ['60 W', '100 W', '120 W', '200 W'], 2, 'Z=√(30²+40²)=50 Ω. I=100/50=2 A. P=I²R=4×30=120 W.']);
  add('physics/electromagnetism/em_waves', 'Electromagnetic waves in vacuum have perpendicular electric and magnetic fields, with E/B=c. Frequency is fixed by the source; wavelength changes when a wave enters a medium. Increasing frequency increases photon energy but does not increase the vacuum propagation speed.',
    ['A vacuum electromagnetic wave has frequency 6×10¹⁴ Hz. With c=3×10⁸ m/s, its wavelength is:', ['50 nm', '500 nm', '5 μm', '50 μm'], 1, 'λ=c/f=5×10⁻⁷ m=500 nm.'],
    ['The peak electric field of a plane wave in vacuum is 600 V/m. The peak magnetic field is (c=3×10⁸ m/s):', ['0.2 μT', '2 μT', '20 μT', '200 μT'], 1, 'B₀=E₀/c=600/(3×10⁸)=2×10⁻⁶ T=2 μT.']);
  add('physics/optics/ray', 'Keep one optical sign convention throughout a calculation. Lens power adds for thin lenses in contact; focal lengths do not. For total internal reflection light must travel from the optically denser to the rarer medium and exceed the critical angle.',
    ['Thin lenses of focal lengths +20 cm and -50 cm are in contact in air. Equivalent power is:', ['+3 D', '+7 D', '-3 D', '-7 D'], 0, 'P=1/0.20+1/(-0.50)=5-2=+3 D.'],
    ['An object is 30 cm in front of a convex lens of focal length 20 cm. Under Cartesian signs u=-30 cm and f=+20 cm. Image distance is:', ['12 cm', '30 cm', '60 cm', '-60 cm'], 2, '1/f=1/v-1/u gives 1/v=1/20-1/30=1/60. The real image is 60 cm behind the lens.']);
  add('physics/optics/wave', 'Interference requires coherent waves with stable phase difference. In Young’s experiment fringe width increases with wavelength and screen distance but decreases with slit separation. Diffraction minima for a single slit follow a different condition from double-slit interference maxima.',
    ['In Young’s experiment λ=600 nm, slit spacing=0.30 mm and screen distance=1 m. Fringe width is:', ['0.2 mm', '1 mm', '2 mm', '5 mm'], 2, 'β=λD/d=600×10⁻⁹/(0.30×10⁻³)=0.002 m=2 mm.'],
    ['Two coherent waves of equal intensity I meet with phase difference 120°. The resulting intensity is:', ['0', 'I', '2I', '4I'], 1, 'I_result=I+I+2I cos120°=2I-I=I.']);
  add('physics/modern_physics/dual_nature', 'Photoelectric emission depends on frequency exceeding the threshold. Above threshold, intensity mainly changes electron count, while frequency changes maximum kinetic energy. The de Broglie wavelength depends on momentum; for a nonrelativistic electron accelerated through V, it varies as V^(-1/2).',
    ['Photons of energy 5 eV illuminate a metal of work function 2 eV. Stopping potential is:', ['2 V', '3 V', '5 V', '7 V'], 1, 'K_max=hf-φ=3 eV, so eV_s=3 eV and V_s=3 V.'],
    ['The accelerating voltage for a nonrelativistic electron rises from 100 V to 900 V. Its de Broglie wavelength becomes:', ['λ/9', 'λ/3', '3λ', '9λ'], 1, 'Momentum∝√V and λ=h/p. Thus λ_new/λ_old=√(100/900)=1/3.']);
  add('physics/modern_physics/atoms', 'Hydrogen-like energy levels scale as -Z²/n². Emission photon energy is the difference between two levels, not either level itself. Radioactive half-life applies to undecayed nuclei; after several half-lives distinguish the surviving fraction from the decayed fraction.',
    ['A radioactive sample has half-life 6 h. The fraction remaining after 18 h is:', ['1/2', '1/4', '1/8', '1/16'], 2, '18 h equals three half-lives; surviving fraction=(1/2)³=1/8.'],
    ['For He⁺, E_n=-13.6Z²/n² eV. Energy released in the n=2 to n=1 transition is:', ['10.2 eV', '13.6 eV', '40.8 eV', '54.4 eV'], 2, 'Z=2. E₂=-13.6 eV and E₁=-54.4 eV. Emitted energy=54.4-13.6=40.8 eV.']);
  add('physics/modern_physics/semiconductors', 'Doping changes majority-carrier concentration but the bulk semiconductor remains electrically neutral. Forward bias reduces a junction barrier; reverse bias increases it. A transistor current gain relates changes in collector and base currents in the active region, not unlimited current amplification.',
    ['A transistor has current gain β=100 and base current 20 μA in the active region. Collector current is:', ['0.2 mA', '2 mA', '20 mA', '200 mA'], 1, 'I_C=βI_B=100×20 μA=2000 μA=2 mA.'],
    ['A 5 V supply feeds a forward-biased silicon diode (constant drop 0.7 V) and a 1 kΩ series resistor. Current is approximately:', ['0.7 mA', '4.3 mA', '5 mA', '5.7 mA'], 1, 'The resistor has 5-0.7=4.3 V across it. I=4.3/1000=4.3 mA.']);
  add('chemistry/physical/mole', 'Balance an equation before comparing amounts. The limiting reagent is the reactant that gives the smaller product amount after division by its stoichiometric coefficient. Gas volumes are proportional to moles only when temperature and pressure are the same.',
    ['For N₂+3H₂→2NH₃, 2 mol N₂ and 3 mol H₂ react completely as far as possible. Ammonia formed is:', ['1 mol','2 mol','3 mol','4 mol'], 1, 'Hydrogen limits the reaction: 3 mol H₂ makes 2 mol NH₃ and consumes 1 mol N₂.'],
    ['A 10.0 g impure CaCO₃ sample gives 1.76 g CO₂ on complete reaction with excess acid. Use molar masses CaCO₃=100 and CO₂=44 g/mol. Purity is:', ['20%','40%','60%','80%'], 1, 'n(CO₂)=1.76/44=0.040 mol. The same moles of CaCO₃ weigh 4.0 g. Purity=4/10×100=40%.']);
  add('chemistry/physical/atom', 'Quantum numbers constrain allowed electronic states: l ranges from 0 to n-1 and m_l from -l to +l. An orbital accommodates two electrons of opposite spin. For hydrogen-like ions transition energies scale with Z²; this simple expression does not directly describe multielectron atoms.',
    ['The maximum number of electrons in a subshell with l=2 is:', ['2','6','10','14'], 2, 'There are 2l+1=5 orbitals, each with two spin states: 10 electrons.'],
    ['An electron has n=4 and l=3. How many possible m_l values are allowed?', ['3','4','7','9'], 2, 'm_l=-3,-2,-1,0,1,2,3: seven possible values.']);
  add('chemistry/physical/states', 'Use absolute temperature and consistent pressure units in gas laws. Real gases depart from ideal behaviour at high pressure and low temperature. Dalton’s law uses mole fractions for an ideal gas mixture; partial pressure is not mass fraction multiplied by total pressure.',
    ['An ideal gas occupies 2 L at 300 K. At constant pressure, its volume at 450 K is:', ['1 L','2 L','3 L','4 L'], 2, 'V₂/V₁=T₂/T₁=450/300; V₂=3 L.'],
    ['A mixture contains 2 g H₂ and 16 g O₂ at total pressure 6 atm. With molar masses 2 and 32 g/mol, partial pressure of H₂ is:', ['2 atm','3 atm','4 atm','5 atm'], 2, 'n(H₂)=1 mol; n(O₂)=0.5 mol. Mole fraction H₂=1/1.5=2/3; P_H₂=4 atm.']);
  add('chemistry/physical/thermodynamics', 'For chemical thermodynamics ΔU=q+w with work on the system positive. At constant pressure q_p=ΔH when only pressure-volume work occurs. Spontaneity is determined by ΔG=ΔH-TΔS, with entropy converted to the same energy units as enthalpy.',
    ['For a reaction, ΔH=-50 kJ/mol and ΔS=-100 J mol⁻¹ K⁻¹. At 300 K, ΔG is:', ['-80 kJ/mol','-50 kJ/mol','-20 kJ/mol','+20 kJ/mol'], 2, 'Convert ΔS=-0.100 kJ mol⁻¹ K⁻¹. ΔG=-50-300(-0.100)=-20 kJ/mol.'],
    ['A reaction has ΔH=+60 kJ/mol and ΔS=+150 J mol⁻¹ K⁻¹. Assuming these are temperature-independent, it becomes spontaneous at:', ['T<200 K','T>400 K','All temperatures','No temperature'], 1, 'ΔG<0 requires 60000-150T<0, so T>400 K. At exactly 400 K, ΔG=0.']);
  add('chemistry/physical/equilibrium', 'Equilibrium constants depend on temperature, not on the initial composition. Reaction quotient Q predicts the direction of approach to equilibrium. Weak-acid approximations require small dissociation; in very dilute solutions, water autoionisation cannot be ignored.',
    ['A weak monoprotic acid has C=0.10 mol/L and K_a=1.0×10⁻⁵. Ignoring water ionisation and using small dissociation, its pH is:', ['2','3','4','5'], 1, '[H⁺]≈√(K_aC)=√10⁻⁶=10⁻³ mol/L, so pH≈3. Dissociation is 1%, supporting the approximation.'],
    ['For N₂O₄(g)⇌2NO₂(g), K_c=0.20. If equilibrium [NO₂]=0.10 mol/L, equilibrium [N₂O₄] is:', ['0.005 mol/L','0.020 mol/L','0.050 mol/L','0.20 mol/L'], 2, 'K_c=[NO₂]²/[N₂O₄]. Hence [N₂O₄]=0.10²/0.20=0.050 mol/L.']);
  add('chemistry/physical/redox', 'Assign oxidation numbers before identifying electron transfer. The total increase and decrease in oxidation number must balance after atom counts are included. Equivalent mass depends on the reaction medium because the same oxidant may undergo different changes in oxidation state.',
    ['In acidic solution, Mn in MnO₄⁻ is reduced to Mn²⁺. Electrons gained per permanganate ion are:', ['2','3','5','7'], 2, 'Mn goes from +7 to +2, gaining 5 electrons.'],
    ['How many moles of Fe²⁺ are oxidised by 0.020 mol Cr₂O₇²⁻ in acid?', ['0.020','0.040','0.060','0.120'], 3, 'Each dichromate ion gains 6 electrons when two Cr(VI) become Cr(III). Fe²⁺ supplies one electron per ion, giving 6×0.020=0.120 mol.']);
  add('chemistry/physical/electrochemistry', 'Reduction occurs at the cathode in both galvanic and electrolytic cells, but electrode signs differ. Use reduction potentials consistently when finding cell emf. Faraday’s law uses the number of electrons per deposited atom; Nernst calculations use the balanced overall reaction quotient.',
    ['How much copper deposits from Cu²⁺ on passing 1930 C? Use F=96500 C/mol and M(Cu)=63.5 g/mol.', ['0.3175 g','0.635 g','1.27 g','6.35 g'], 1, 'n(e⁻)=1930/96500=0.020 mol; n(Cu)=0.010 mol. Mass=0.010×63.5=0.635 g.'],
    ['At 298 K a two-electron cell has E°=1.10 V and Q=100. Using E=E°-(0.0592/n)log₁₀Q, its emf is:', ['0.9816 V','1.0408 V','1.10 V','1.1592 V'], 1, 'E=1.10-(0.0592/2)×2=1.0408 V.']);
  add('chemistry/physical/kinetics', 'Reaction order is experimentally determined, not generally read from overall stoichiometry. For a first-order process the half-life is independent of initial concentration. Count the fraction remaining, rather than the fraction reacted, when using integrated rate laws.',
    ['A first-order reaction has half-life 10 min. Percentage of reactant remaining after 30 min is:', ['6.25%','12.5%','25%','87.5%'], 1, 'Three half-lives leave (1/2)³=1/8=12.5%. The reacted percentage is 87.5%.'],
    ['For rate=k[A]²[B], [A] doubles and [B] is halved. The rate changes by a factor of:', ['1/2','1','2','4'], 2, 'Rate multiplier=2²×(1/2)=2. Overall order is 3.']);
  add('chemistry/physical/surface', 'Adsorption is a surface process, whereas absorption involves the bulk. Physical adsorption is usually favoured by lower temperature and larger surface area. Colloidal stability depends on particle interactions; counter-ion charge strongly affects coagulation of charged sols.',
    ['A substance follows x/m=kP^(1/2) in a stated pressure range. If pressure increases fourfold, adsorption per unit mass becomes:', ['Half','Double','Fourfold','Unchanged'], 1, '(x/m)₂/(x/m)₁=(P₂/P₁)^(1/2)=√4=2. The isotherm applies only in its specified range.'],
    ['For a negatively charged sol, which ion has the greatest coagulating power under the Hardy-Schulze rule?', ['Na⁺','K⁺','Ca²⁺','Al³⁺'], 3, 'The effective coagulating ion is the counter-ion. Higher counter-ion charge gives greater coagulating power; Al³⁺ exceeds Ca²⁺ and monovalent ions.']);
  add('chemistry/inorganic/periodicity', 'Periodic trends result from nuclear charge, screening and shell structure. Successive ionisation energies reveal when removal begins from a closed inner shell. Exceptions within a period often arise from subshell energy differences or electron-pair repulsion.',
    ['An element has successive ionisation energies 590, 1145, 4910 and 6490 kJ/mol. Its most likely number of valence electrons is:', ['1','2','3','4'], 1, 'The large jump occurs after the second electron; two outer electrons are removed before an inner-shell electron is reached.'],
    ['Which order of first ionisation energy is correct for B, Be, C, N and O?', ['B<Be<C<O<N','Be<B<C<N<O','B<C<Be<O<N','B<Be<O<C<N'], 0, 'B loses a 2p electron more easily than Be loses a 2s electron. Paired-electron repulsion makes O lower than the half-filled 2p³ configuration of N.']);
  add('chemistry/inorganic/bonding', 'Count valence electrons before drawing a Lewis structure, then distinguish electron-domain geometry from molecular shape. In molecular-orbital theory bond order equals half the bonding-minus-antibonding electron count. Unpaired electrons determine paramagnetism.',
    ['For O₂, there are 10 bonding and 6 antibonding electrons in the usual MO count. Bond order is:', ['1','1.5','2','3'], 2, 'Bond order=(10-6)/2=2.'],
    ['Removing one electron from an antibonding orbital of O₂ produces O₂⁺. Its bond order and relative bond length are:', ['1.5; longer','2; unchanged','2.5; shorter','3; longer'], 2, 'Removing an antibonding electron raises bond order by 0.5, to 2.5. Greater bond order usually corresponds to a shorter bond.']);
  add('chemistry/inorganic/s_block', 'Alkaline-earth hydroxide solubility generally increases down the group, while sulfate solubility generally decreases. Thermal stability of carbonates increases as cation polarising power falls. Flame colours result from electronic transitions, not from the colour of the dissolved ion.',
    ['A 0.010 mol sample of CaCO₃ is heated to complete decomposition. Moles of CO₂ evolved are:', ['0.005','0.010','0.020','0.030'], 1, 'CaCO₃→CaO+CO₂ gives one mole CO₂ per mole carbonate: 0.010 mol.'],
    ['Which alkaline-earth sulfate is least soluble in water among these?', ['MgSO₄','CaSO₄','SrSO₄','BaSO₄'], 3, 'Sulfate solubility generally decreases down Group 2. The decreasing hydration benefit makes BaSO₄ very sparingly soluble.']);
  add('chemistry/inorganic/p_block', 'Use oxidation-state bookkeeping together with molecular structure. The inert-pair effect increases the relative stability of lower oxidation states down heavier p-block groups. Electron-deficient compounds can accept lone pairs; a complete octet in a Lewis structure does not by itself establish every bonding property.',
    ['In H₃PO₂ the oxidation state of phosphorus is:', ['-1','+1','+3','+5'], 1, '3(+1)+x+2(-2)=0, so x=+1.'],
    ['A sample contains 0.20 mol NH₃. Complete conversion by 4NH₃+5O₂→4NO+6H₂O requires how much O₂?', ['0.10 mol','0.20 mol','0.25 mol','0.40 mol'], 2, 'The O₂:NH₃ ratio is 5:4. Required O₂=0.20×5/4=0.25 mol.']);
  add('chemistry/inorganic/d_f_block', 'For transition-metal cations remove ns electrons before (n-1)d electrons. Variable oxidation states reflect comparable orbital energies. The spin-only magnetic moment estimates the contribution of unpaired electrons and omits orbital contributions, so it is an approximation.',
    ['How many d electrons are present in Fe³⁺? Atomic number of Fe is 26.', ['3','4','5','6'], 2, 'Fe=[Ar]3d⁶4s². Remove two 4s electrons and one 3d electron: Fe³⁺=[Ar]3d⁵.'],
    ['For an ion with four unpaired electrons, the spin-only magnetic moment √[n(n+2)] is approximately:', ['2.83 BM','3.87 BM','4.90 BM','5.92 BM'], 2, 'With n=4, μ=√(4×6)=√24≈4.90 Bohr magnetons.']);
  add('chemistry/inorganic/coordination', 'Coordination number counts donor atoms, not necessarily ligands. Determine oxidation state before assigning d-electron count. Strong-field octahedral complexes can pair electrons; cis-trans and optical isomerism depend on ligand arrangement and symmetry.',
    ['The oxidation state and coordination number of Co in [Co(NH₃)₆]Cl₃ are:', ['+2 and 6','+3 and 3','+3 and 6','0 and 6'], 2, 'Three external chloride ions balance a +3 complex. NH₃ is neutral and monodentate, so Co is +3 and coordination number is 6.'],
    ['In low-spin octahedral [Fe(CN)₆]⁴⁻, the number of unpaired electrons is:', ['0','2','4','6'], 0, 'Six CN⁻ ligands contribute -6, giving Fe²⁺ (d⁶). Strong-field pairing gives t₂g⁶e_g⁰, with no unpaired electrons.']);
  add('chemistry/organic/principles', 'Count rings and pi bonds through degree of unsaturation before proposing structures. Resonance changes electron distribution without moving atomic positions. Mechanism selection depends on substrate, reagent, solvent and temperature rather than on one mnemonic alone.',
    ['The degree of unsaturation of C₆H₆ is:', ['1','2','3','4'], 3, 'DBE=(2C+2-H)/2=(12+2-6)/2=4. Benzene has one ring and three pi bonds.'],
    ['Which carbocation is most stabilised by resonance?', ['CH₃⁺','CH₃CH₂⁺','C₆H₅CH₂⁺','CH₂=CH⁺'], 2, 'The benzyl cation delocalises positive charge into the aromatic ring. The vinyl cation has its positive centre on a double-bond carbon and lacks this benzyl stabilisation.']);
  add('chemistry/organic/hydrocarbons', 'Electrophilic additions to unsymmetrical alkenes depend on intermediate stability. Peroxide-driven anti-Markovnikov addition is characteristic of HBr under suitable radical conditions, not a universal rule for all hydrogen halides. Ozonolysis identifies the original double-bond carbon skeleton.',
    ['Propene reacts with HBr in the absence of peroxides. The main product is:', ['1-bromopropane','2-bromopropane','1,2-dibromopropane','Propanol'], 1, 'Ionic addition proceeds mainly through the more stable secondary carbocation, giving 2-bromopropane.'],
    ['Reductive ozonolysis of an acyclic alkene gives only propanone (two molecules per alkene). The alkene is:', ['But-2-ene','2-methylpropene','2,3-dimethylbut-2-ene','Hex-3-ene'], 2, 'Reconnect the two carbonyl carbons of two propanone molecules. The result is (CH₃)₂C=C(CH₃)₂, or 2,3-dimethylbut-2-ene.']);
  add('chemistry/organic/haloalkanes', 'SN2 involves backside attack and inversion at a reacting stereocentre; steric crowding slows it. SN1 involves a carbocation and may undergo rearrangement. Alcoholic base and heat often favour elimination, while aqueous hydroxide commonly favours substitution for suitable substrates.',
    ['Which substrate reacts fastest by SN2 with the same nucleophile under comparable conditions?', ['CH₃Br','(CH₃)₂CHBr','(CH₃)₃CBr','Bromobenzene'], 0, 'Methyl bromide offers minimal steric hindrance. Tertiary alkyl bromide is strongly hindered, and aryl halides do not undergo ordinary SN2 at the ring carbon.'],
    ['One mole of 2-bromobutane undergoes complete dehydrohalogenation. Maximum moles of HBr eliminated are:', ['0.5','1','2','4'], 1, 'Each molecule loses one H and one Br to form one alkene molecule. Thus one mole substrate eliminates one mole HBr equivalent.']);
  add('chemistry/organic/alcohols', 'Alcohol acidity depends on the stability of its conjugate base. Phenoxide is resonance-stabilised, unlike a simple alkoxide. Oxidation products depend on whether the alcohol is primary, secondary or tertiary and on reagent strength and work-up conditions.',
    ['Controlled oxidation of propan-2-ol yields:', ['Propanal','Propanone','Propanoic acid','Propene'], 1, 'A secondary alcohol oxidises to a ketone: CH₃CHOHCH₃→CH₃COCH₃.'],
    ['How many moles of H₂ are released when 0.20 mol ethanol reacts completely with excess sodium?', ['0.05','0.10','0.20','0.40'], 1, '2C₂H₅OH+2Na→2C₂H₅ONa+H₂. Hydrogen yield is half the alcohol amount: 0.10 mol.']);
  add('chemistry/organic/carbonyls', 'Aldehydes are generally more easily oxidised than ketones. Aldol reactions require an appropriate alpha hydrogen, whereas the Cannizzaro reaction involves suitable aldehydes without alpha hydrogen under concentrated base. Carboxylic-acid derivatives undergo nucleophilic acyl substitution rather than simple carbonyl addition.',
    ['Which compound gives a positive Tollens test under standard conditions?', ['Propanone','Ethanal','Ethanoic acid','Ethyl ethanoate'], 1, 'Ethanal is an aldehyde and reduces the silver complex while being oxidised to carboxylate. The other listed compounds do not give the standard aldehyde reaction.'],
    ['In the Cannizzaro reaction, 0.10 mol benzaldehyde reacts completely. Moles of benzyl alcohol produced are:', ['0.025','0.050','0.100','0.200'], 1, 'Two aldehyde molecules disproportionate into one alcohol and one carboxylate. Thus 0.10 mol aldehyde produces 0.050 mol benzyl alcohol.']);
  add('chemistry/organic/amines', 'Basicity depends on lone-pair availability and solvation. In aniline the nitrogen lone pair participates in ring delocalisation, reducing basicity compared with a typical aliphatic amine. Diazotisation of primary aromatic amines requires cold conditions to preserve the diazonium salt.',
    ['Which is more basic in water under ordinary conditions?', ['Aniline','Methylamine','Acetamide','Nitrobenzene'], 1, 'Methylamine has an available nitrogen lone pair and an electron-donating methyl group. Aniline and amide lone pairs are delocalised; nitrobenzene is not an amine base.'],
    ['In a Hofmann bromamide rearrangement, propanamide gives which primary amine?', ['Methylamine','Ethylamine','Propylamine','Butylamine'], 1, 'The carbonyl carbon is lost. CH₃CH₂CONH₂ gives CH₃CH₂NH₂, ethylamine, with one fewer carbon.']);
  add('chemistry/organic/biomolecules', 'Separate monomer composition from the linkage joining monomers. Peptide formation is a condensation between amino and carboxyl groups; reducing sugars require an accessible reducing functionality. A molecule can contain several stereocentres without having the maximum possible number of stereoisomers because of symmetry.',
    ['A linear peptide made from six amino-acid residues contains how many peptide bonds?', ['4','5','6','7'], 1, 'A linear chain of n residues has n-1 peptide bonds; 6-1=5.'],
    ['Complete hydrolysis of 0.15 mol sucrose produces how many total moles of monosaccharides?', ['0.075','0.15','0.30','0.45'], 2, 'Each sucrose molecule yields one glucose and one fructose. Total monosaccharides=2×0.15=0.30 mol.']);
  add('chemistry/organic/polymers', 'Addition polymerisation usually retains the monomer atoms in the repeat unit, whereas many condensation polymerisations release small molecules. Distinguish repeat-unit molar mass from whole-polymer molar mass. Biodegradability depends on bond chemistry and environment, not solely on whether a material is synthetic.',
    ['Polyethene has repeat-unit molar mass 28 g/mol and average molar mass 28000 g/mol. Approximate degree of polymerisation is:', ['100','500','1000','2000'], 2, 'Degree of polymerisation≈28000/28=1000 repeat units, neglecting end-group mass.'],
    ['Which pair forms nylon-6,6 by condensation polymerisation?', ['Ethene and propene','Hexamethylenediamine and adipic acid','Phenol and ethene','Styrene and glucose'], 1, 'A diamine and a dicarboxylic acid form repeated amide linkages, releasing water. Six carbons in each monomer give the 6,6 designation.']);
  add('biology/diversity_structure/classification', 'Classify using multiple characters rather than habitat alone. Prokaryotes lack a membrane-bound nucleus, while fungi are eukaryotic absorptive heterotrophs. Viruses are acellular and depend on host machinery; similarity in disease symptoms does not establish taxonomic relatedness.',
    ['An organism has chitinous cell walls, no chlorophyll and extracellular digestion. It most likely belongs to:', ['Plantae','Fungi','Monera','Animalia'], 1, 'The combination of chitin walls and absorptive heterotrophy characterises fungi.'],
    ['A culture starts with 125 bacterial cells. With a constant 20-minute doubling time and no death, the population after 2 hours is:', ['750','4000','8000','16000'], 2, 'There are 120/20=6 generations. N=125×2⁶=8000 cells. This assumes unrestricted exponential growth.']);
  add('biology/diversity_structure/plant_kingdom', 'Identify the dominant generation and vascular tissues when distinguishing plant groups. Bryophyte sporophytes depend on the gametophyte; pteridophytes have independent vascular sporophytes but still require water for fertilisation. Seeds protect an embryo and distinguish seed plants from spore-only groups.',
    ['A vascular plant reproduces by spores and requires free water for fertilisation. It is most likely a:', ['Moss','Fern','Pine','Grass'], 1, 'Ferns are vascular pteridophytes with motile sperm. Mosses are nonvascular; pine and grass are seed plants.'],
    ['A fern sporophyte has 48 chromosomes per somatic nucleus. Chromosome numbers in a spore and in a gamete are respectively:', ['48 and 24','24 and 24','24 and 12','48 and 48'], 1, 'Meiosis in the sporophyte makes n=24 spores. The haploid gametophyte makes gametes by mitosis, so gametes also have 24.']);
  add('biology/diversity_structure/animal_kingdom', 'Body symmetry, germ layers, coelom and segmentation help distinguish animal phyla. Adult echinoderms are radially symmetric but their larvae are bilateral. A notochord may occur only during part of development, so adult appearance alone can obscure chordate relationships.',
    ['Which combination best identifies an adult annelid?', ['Radial symmetry and cnidocytes','Metameric segmentation and true coelom','Jointed appendages and chitinous exoskeleton','Water vascular system and tube feet'], 1, 'Annelids are segmented coelomates. Jointed appendages indicate arthropods; a water vascular system indicates echinoderms.'],
    ['An animal has a dorsal hollow nerve cord and pharyngeal slits during development but no vertebral column. Which conclusion follows?', ['It cannot be a chordate','It must be an arthropod','It may be an invertebrate chordate','It must be a mammal'], 2, 'Chordate features do not require vertebrae. Tunicates and lancelets provide invertebrate chordate examples.']);
  add('biology/diversity_structure/morphology', 'Relate plant tissue arrangement to transport and growth. Xylem and phloem differ in transported materials and cell types. Distinguish homologous modifications by their developmental origin rather than by the similarity of their storage or support functions.',
    ['A potato tuber and a sweet-potato storage organ are respectively modified:', ['Roots and stems','Stems and roots','Leaves and roots','Stems and leaves'], 1, 'Potato tubers are stems with nodes and buds; sweet-potato storage organs are roots.'],
    ['A flower has five fused petals, five free sepals, ten stamens and a superior ovary. Which statement is supported?', ['It is necessarily unisexual','Its corolla is gamopetalous','Its calyx is gamosepalous','Its ovary must be inferior'], 1, 'Fused petals define a gamopetalous corolla. Free sepals are polysepalous; the given superior ovary contradicts the inferior-ovary option.']);
  add('biology/diversity_structure/organization', 'Tissue identity depends on cell structure, extracellular matrix and function. Epithelium covers surfaces with closely packed cells; connective tissues have more extracellular material. Skeletal muscle is striated and usually voluntary, whereas cardiac muscle is striated with specialised junctions.',
    ['Which tissue is best suited for rapid diffusion across alveolar walls?', ['Stratified squamous epithelium','Simple squamous epithelium','Transitional epithelium','Keratinised epithelium'], 1, 'A thin single layer minimises diffusion distance. Multiple layers improve protection but impede exchange.'],
    ['An animal tissue is striated, branched and joined by intercalated discs. It is:', ['Smooth muscle','Skeletal muscle','Cardiac muscle','Dense connective tissue'], 2, 'Branching striated fibres and intercalated discs identify cardiac muscle, supporting coordinated contraction.']);
  add('biology/cell_biology/cell_life', 'Surface-area-to-volume ratio declines as a cell grows without changing shape. Membranes regulate transport by permeability and proteins; diffusion and active transport differ in energy requirements. A larger organelle count cannot be inferred from cell size alone.',
    ['A spherical cell doubles its radius without changing shape. Its surface-area-to-volume ratio becomes:', ['Twice','Four times','Half','Unchanged'], 2, 'For a sphere SA/V=3/r. Doubling r halves this ratio, even though both area and volume increase.'],
    ['A plant cell is placed in a solution with lower water potential than its cytoplasm. The immediate net water movement is:', ['Into the cell','Out of the cell','No movement','Into the nucleus only'], 1, 'Water moves down its water-potential gradient. Water loss can cause plasmolysis as the protoplast shrinks from the wall.']);
  add('biology/cell_biology/biomolecules', 'Enzymes lower activation energy without changing reaction equilibrium. Competitive inhibition can be overcome by sufficient substrate in the ideal model. Protein denaturation disrupts higher-order structure; it does not necessarily hydrolyse the peptide backbone.',
    ['For a Michaelis-Menten enzyme at [S]=K_m, reaction velocity is:', ['V_max','V_max/2','V_max/4','Zero'], 1, 'v=V_max[S]/(K_m+[S]); substituting [S]=K_m gives V_max/2.'],
    ['An ideal competitive inhibitor changes apparent K_m and V_max in which way?', ['Both decrease','K_m rises; V_max unchanged','K_m unchanged; V_max falls','Both rise'], 1, 'Competition reduces apparent substrate affinity, increasing K_m. At sufficiently high substrate the same V_max can be approached.']);
  add('biology/cell_biology/cell_cycle', 'Count chromosomes by centromeres and distinguish chromosome number from DNA content. DNA doubles in S phase without doubling chromosome count. Meiosis I separates homologues; meiosis II separates sister chromatids, producing haploid products after one replication and two divisions.',
    ['A diploid cell has 2n=16. At metaphase of mitosis it contains:', ['8 chromosomes and 16 chromatids','16 chromosomes and 16 chromatids','16 chromosomes and 32 chromatids','32 chromosomes and 32 chromatids'], 2, 'DNA has replicated. There remain 16 centromere-defined chromosomes, each with two chromatids: 32 chromatids.'],
    ['A primary meiocyte has 2n=12. Immediately after meiosis I, each daughter nucleus normally contains:', ['12 chromosomes, 12 chromatids','6 chromosomes, 12 chromatids','6 chromosomes, 6 chromatids','3 chromosomes, 6 chromatids'], 1, 'Homologues separate in meiosis I, giving n=6 chromosomes. Each still has two sister chromatids, giving 12 chromatids.']);
  add('biology/plant_physiology/transport', 'Water potential combines solute and pressure components. Dissolved solute makes solute potential more negative, while positive turgor raises water potential. Transpiration creates tension in xylem; phloem transport instead involves source-sink pressure differences.',
    ['A cell has solute potential -0.8 MPa and pressure potential +0.3 MPa. Its water potential is:', ['-1.1 MPa','-0.5 MPa','+0.5 MPa','+1.1 MPa'], 1, 'Ψ_w=Ψ_s+Ψ_p=-0.8+0.3=-0.5 MPa.'],
    ['Cells A and B have water potentials -0.2 MPa and -0.7 MPa. Across a water-permeable membrane, initial net movement is:', ['A to B','B to A','Neither direction','Determined only by cell size'], 0, 'Water initially moves from higher (less negative) potential A to lower potential B.']);
  add('biology/plant_physiology/photosynthesis', 'Light reactions supply ATP and NADPH; the Calvin cycle consumes them while fixing carbon. Oxygen evolved in oxygenic photosynthesis comes from water. C4 plants initially fix carbon into four-carbon compounds and concentrate CO₂ near RuBisCO, reducing photorespiration.',
    ['Ignoring photorespiration, the Calvin cycle needs how many ATP and NADPH to produce one net triose phosphate from 3 CO₂?', ['3 ATP, 3 NADPH','6 ATP, 6 NADPH','9 ATP, 6 NADPH','18 ATP, 12 NADPH'], 2, 'Fixation and reduction of 3 CO₂ to one net G3P consume 9 ATP and 6 NADPH.'],
    ['Under the ideal Calvin-cycle stoichiometry, fixation of 12 CO₂ into carbohydrate requires:', ['18 ATP and 12 NADPH','24 ATP and 24 NADPH','36 ATP and 24 NADPH','72 ATP and 48 NADPH'], 2, 'Per CO₂, the cycle consumes 3 ATP and 2 NADPH. For 12 CO₂: 36 ATP and 24 NADPH.']);
  add('biology/plant_physiology/respiration', 'Track carbon atoms as well as ATP and reduced coenzymes. Glycolysis occurs in the cytosol, while the citric-acid cycle is mitochondrial in eukaryotes. Respiratory quotient is CO₂ released divided by O₂ consumed and depends on the substrate.',
    ['Complete aerobic oxidation of glucose follows C₆H₁₂O₆+6O₂→6CO₂+6H₂O. Respiratory quotient is:', ['0.5','0.7','1.0','1.5'], 2, 'RQ=CO₂/O₂=6/6=1.'],
    ['A tissue releases 0.36 mol CO₂ while consuming 0.50 mol O₂. Its respiratory quotient is:', ['0.36','0.50','0.72','1.39'], 2, 'RQ=0.36/0.50=0.72. This is consistent with substantial lipid oxidation, but does not uniquely identify a substrate mixture.']);
  add('biology/plant_physiology/growth', 'Separate absolute growth from relative growth. Plant hormones interact and can have concentration-dependent effects. Photoperiod responses often depend on uninterrupted night length; the critical day length is species-specific rather than a universal 12-hour boundary.',
    ['A plant increases dry mass from 10 g to 15 g in 5 days. Mean absolute growth rate is:', ['0.2 g/day','1 g/day','2 g/day','5 g/day'], 1, 'Absolute growth rate=(15-10)/5=1 g/day.'],
    ['A short-day plant receives a long night interrupted by an effective red-light pulse. Flowering is most likely:', ['Promoted in every species','Inhibited in a night-break-sensitive species','Unaffected in all plants','Independent of phytochrome'], 1, 'An effective night break can make the plant perceive a short night and inhibit flowering. The effect depends on species and experimental conditions.']);
  add('biology/human_physiology/digestion', 'Digestion hydrolyses macromolecules; absorption transfers products across epithelia. Bile emulsifies fats but is not a digestive enzyme. For ventilation, distinguish the total air moved per minute from fresh air reaching gas-exchanging surfaces after anatomical dead space is accounted for.',
    ['Tidal volume is 500 mL and respiratory rate is 12/min. Minute ventilation is:', ['3.6 L/min','4.2 L/min','6.0 L/min','7.8 L/min'], 2, 'Minute ventilation=500×12=6000 mL/min=6.0 L/min.'],
    ['Tidal volume is 500 mL, anatomical dead space 150 mL and respiratory rate 16/min. Alveolar ventilation is:', ['2.4 L/min','5.6 L/min','8.0 L/min','10.4 L/min'], 1, 'Alveolar ventilation=(500-150)×16=5600 mL/min=5.6 L/min.']);
  add('biology/human_physiology/circulation', 'Cardiac output equals heart rate multiplied by stroke volume. Pressure falls through the systemic circulation, but total capillary area makes average capillary speed low. Oxygenated and deoxygenated describe blood composition; artery and vein describe direction relative to the heart.',
    ['Heart rate is 75/min and stroke volume is 80 mL. Cardiac output is:', ['4 L/min','5 L/min','6 L/min','8 L/min'], 2, 'CO=75×80=6000 mL/min=6 L/min.'],
    ['Using MAP≈diastolic pressure+(pulse pressure/3), estimated mean arterial pressure for 120/75 mmHg is:', ['80 mmHg','90 mmHg','95 mmHg','105 mmHg'], 1, 'Pulse pressure=120-75=45. MAP≈75+45/3=90 mmHg. This is an approximation for an ordinary resting heart rate.']);
  add('biology/human_physiology/excretion', 'Filtration, reabsorption and secretion are distinct nephron processes. A freely filtered marker with neither reabsorption nor secretion can estimate GFR from clearance. ADH increases water permeability in responsive distal nephron regions and collecting ducts; it does not simply increase filtration.',
    ['A person filters 180 L/day and excretes 1.8 L urine/day. Approximate fraction of filtered water reabsorbed is:', ['90%','95%','99%','99.9%'], 2, 'Reabsorbed volume=180-1.8=178.2 L. Fraction=178.2/180=0.99=99%.'],
    ['A freely filtered, neither secreted nor reabsorbed marker has urine concentration 120 mg/mL, plasma concentration 1 mg/mL and urine flow 1 mL/min. Its clearance is:', ['1 mL/min','60 mL/min','120 mL/min','240 mL/min'], 2, 'Clearance=U×V/P=120×1/1=120 mL/min, estimating GFR under the stated assumptions.']);
  add('biology/human_physiology/locomotion', 'Sliding filaments change overlap rather than shortening the actin and myosin filaments themselves. Calcium exposes actin binding sites through the troponin-tropomyosin system. ATP binding detaches a myosin head, while ATP hydrolysis primes it for a subsequent cycle.',
    ['During skeletal-muscle contraction, which sarcomere band remains approximately constant in length?', ['I band','H zone','A band','Entire sarcomere'], 2, 'The A band corresponds to thick-filament length, which does not shorten during sliding. I band and H zone narrow.'],
    ['In the absence of ATP after death, persistent actin-myosin binding occurs primarily because:', ['Calcium cannot bind actin','Myosin cannot detach normally from actin','Actin filaments dissolve','All sarcomeres lose thick filaments'], 1, 'ATP binding is required for myosin detachment. Its absence contributes to rigor mortis.']);
  add('biology/human_physiology/neural', 'An action potential is all-or-none in a single axon; stimulus strength can be coded by firing frequency and recruitment. Saltatory conduction involves regeneration at nodes of Ranvier. Refractory periods limit firing and help enforce propagation direction after a locally triggered impulse.',
    ['An impulse travels 1.2 m along an axon at 60 m/s. Conduction time is:', ['2 ms','20 ms','50 ms','200 ms'], 1, 't=d/v=1.2/60=0.020 s=20 ms.'],
    ['Two synapses each add 0.5 ms delay. An impulse traverses 1 m of axon at 50 m/s and both synapses. Total delay is:', ['20 ms','20.5 ms','21 ms','22 ms'], 2, 'Axonal time=1/50=0.020 s=20 ms. Add 2×0.5 ms=1 ms, giving 21 ms.']);
  add('biology/human_physiology/coordination', 'Negative feedback stabilises many endocrine axes. Distinguish hormone production from storage and release; ADH is synthesised in hypothalamic neurons and released from the posterior pituitary. A target gland and its controlling pituitary hormone can change in opposite directions during primary gland failure.',
    ['Untreated primary hypothyroidism typically produces which hormone pattern?', ['Low thyroxine, high TSH','High thyroxine, high TSH','Low thyroxine, low TSH','High thyroxine, low TSH'], 0, 'A failing thyroid makes less thyroxine. Reduced negative feedback increases pituitary TSH if the pituitary axis is intact.'],
    ['A peptide hormone acts through a surface receptor and cAMP. Which immediate event is most plausible?', ['Direct binding to nuclear DNA','Activation of a membrane-associated signalling cascade','Diffusion of the peptide through the lipid bilayer','Conversion into a steroid'], 1, 'Peptide hormones generally signal through membrane receptors and second messengers rather than freely crossing the lipid bilayer.']);
  add('biology/reproduction_genetics/reproduction', 'In angiosperms double fertilisation forms the diploid zygote and usually triploid primary endosperm nucleus. A single functional megaspore commonly forms an eight-nucleate embryo sac. In humans, distinguish fertilisation from implantation and the maternal from embryonic contributions to pregnancy signalling.',
    ['In a typical angiosperm with 2n=24, the zygote and primary endosperm nucleus contain respectively:', ['12 and 24 chromosomes','24 and 24 chromosomes','24 and 36 chromosomes','36 and 48 chromosomes'], 2, 'n=12. Egg+sperm gives 2n=24; two polar nuclei+sperm give 3n=36.'],
    ['Assuming each pollen mother cell yields four viable pollen grains, how many mother cells are needed for 400 pollen grains?', ['25','50','100','200'], 2, 'Each meiotic mother cell produces a tetrad of four microspores. 400/4=100 mother cells.']);
  add('biology/reproduction_genetics/mendelian', 'State dominance and independent-assortment assumptions before calculating ratios. Multiply probabilities for independent events and add probabilities for mutually exclusive alternatives. A test cross reveals gamete frequencies of the tested parent; linkage changes the expected proportions.',
    ['For Aa×Aa with complete dominance, the probability of a recessive-phenotype offspring is:', ['1/2','1/4','3/4','1'], 1, 'The genotypes are AA:Aa:aa=1:2:1, so P(aa)=1/4.'],
    ['For AaBb×AaBb with independent assortment and complete dominance at both loci, probability of an offspring dominant at A but recessive at B is:', ['1/16','3/16','9/16','1/4'], 1, 'P(A_)=3/4 and P(bb)=1/4. Independent probabilities multiply: 3/4×1/4=3/16.']);
  add('biology/reproduction_genetics/molecular', 'In double-stranded DNA, A pairs with T and G with C, but this equality need not hold for a single strand. Replication is semiconservative. Codons are read on mRNA in the 5′ to 3′ direction, with start and stop signals distinguished from amino-acid codons.',
    ['A double-stranded DNA sample has 20% adenine. Guanine percentage is:', ['20%','25%','30%','40%'], 2, 'T=20%, leaving 60% for G+C. G=C, so each is 30%.'],
    ['A double-stranded DNA molecule has 100 base pairs, 40 of which are G-C pairs. Total hydrogen bonds are:', ['200','220','240','300'], 2, '40 G-C pairs contribute 120 bonds; 60 A-T pairs contribute 120. Total=240.']);
  add('biology/reproduction_genetics/evolution', 'Hardy-Weinberg proportions are a null model requiring specified population assumptions. Recessive phenotype frequency equals q² only with the relevant dominance model. Natural selection acts on heritable variation; individuals do not acquire adaptive mutations because they need them.',
    ['For a recessive trait under Hardy-Weinberg equilibrium, affected frequency is 0.04. Recessive allele frequency q is:', ['0.02','0.04','0.20','0.40'], 2, 'q²=0.04, so q=√0.04=0.20.'],
    ['A Hardy-Weinberg population has q=0.10 for a recessive allele. Expected heterozygote frequency is:', ['0.01','0.09','0.18','0.81'], 2, 'p=0.90. Heterozygote frequency=2pq=2×0.90×0.10=0.18.']);
  add('biology/biotechnology_ecology/biotech', 'Restriction enzymes recognise particular DNA sequences; ligase joins compatible DNA ends. PCR requires primers, template, nucleotides and a thermostable polymerase. Ideal doubling is a teaching model; actual amplification efficiency and plateau effects limit laboratory yield.',
    ['Starting with 5 double-stranded DNA molecules, ideal PCR produces how many after 6 complete doubling cycles?', ['30','160','320','640'], 2, 'N=N₀×2ⁿ=5×2⁶=320 molecules, assuming ideal efficiency each cycle.'],
    ['A circular plasmid contains three distinct recognition sites for one restriction enzyme. Complete digestion gives how many fragments?', ['2','3','4','6'], 1, 'For circular DNA, n distinct cuts produce n fragments. Thus three cuts produce three fragments; linear DNA would give n+1.']);
  add('biology/biotechnology_ecology/health', 'Distinguish a pathogen from its vector and from the host response. Vaccination produces active immune memory, whereas administered antibodies give passive protection. Antibiotics target bacterial processes and should not be assumed to treat a viral infection.',
    ['Which intervention gives immediate passive immunity?', ['A live attenuated vaccine','Injection of specific immunoglobulin','Exposure to a harmless antigen','A booster vaccine'], 1, 'Specific immunoglobulin supplies ready-made antibodies. It does not require the recipient to first generate an adaptive response.'],
    ['In a hypothetical screening study, 90 of 100 truly diseased individuals test positive. Test sensitivity is:', ['10%','50%','90%','Cannot be calculated'], 2, 'Sensitivity=true positives/(true positives+false negatives)=90/100=90%. Specificity and positive predictive value require other counts.']);
  add('biology/biotechnology_ecology/populations', 'Population growth depends on births, deaths, immigration and emigration. Logistic growth includes density dependence through carrying capacity K. Under that model, absolute growth is greatest at N=K/2, whereas per-capita growth declines as N rises.',
    ['A population of 200 has 30 births, 10 deaths, 8 immigrants and 3 emigrants over a period. Final population is:', ['215','220','225','231'], 2, 'N_final=200+30-10+8-3=225.'],
    ['For logistic growth dN/dt=rN(1-N/K), r=0.2/year, K=1000 and N=500. Growth rate is:', ['25/year','50/year','100/year','200/year'], 1, 'Growth=0.2×500×(1-500/1000)=100×0.5=50 individuals/year.']);
  add('biology/biotechnology_ecology/ecology', 'Energy flow through trophic levels is directional, while elements cycle. Distinguish gross primary productivity from net productivity after producer respiration. The ten-percent transfer rule is an approximation for practice calculations, not a fixed efficiency of every ecosystem.',
    ['Gross primary productivity is 2000 kJ m⁻² year⁻¹ and producer respiration is 800 in the same units. NPP is:', ['800','1200','2000','2800'], 1, 'NPP=GPP-respiration=2000-800=1200 kJ m⁻² year⁻¹.'],
    ['Assuming exactly 10% transfer at each trophic step, producers contain 20000 kJ. Energy available to tertiary consumers is:', ['2000 kJ','200 kJ','20 kJ','2 kJ'], 2, 'Producers→primary→secondary→tertiary requires three transfers. 20000×0.1³=20 kJ.']);
  add('mathematics/algebra/sets', 'For a union, subtract overlaps counted twice. Functions must assign exactly one output to each allowed input. Determine the domain before algebraic cancellation: simplifying an expression does not restore inputs excluded by the original denominator.',
    ['In a group of 60, 35 study physics, 30 chemistry and 15 both. How many study neither?', ['5','10','15','20'], 1, '|P∪C|=35+30-15=50. Neither=60-50=10.'],
    ['For f(x)=(x²-1)/(x-1), the domain of f is:', ['All real numbers','All real numbers except 1','All real numbers except -1','Only x>1'], 1, 'The original denominator excludes x=1. Although f(x)=x+1 elsewhere, the cancelled expression cannot restore that excluded input.']);
  add('mathematics/algebra/complex', 'Use conjugates to rationalise complex denominators. Quadratic-root sums and products follow from coefficients, including their signs. A real-coefficient polynomial has nonreal roots in conjugate pairs; this need not hold for polynomials with complex coefficients.',
    ['The value of (1+i)/(1-i) is:', ['1','-1','i','-i'], 2, 'Multiply numerator and denominator by 1+i: (1+i)²/(1+1)=2i/2=i.'],
    ['If α and β are roots of 2x²-3x+5=0, α²+β² equals:', ['-11/4','11/4','-1/4','19/4'], 0, 'α+β=3/2 and αβ=5/2. α²+β²=(α+β)²-2αβ=9/4-5=-11/4.']);
  add('mathematics/algebra/inequalities', 'Multiplication or division by a negative reverses an inequality. For rational inequalities mark zeros and excluded denominator roots separately, then test interval signs. Squaring can introduce extra solutions unless signs of both sides are controlled.',
    ['Solve -3x+7>1.', ['x>2','x<2','x< -2','x≥2'], 1, '-3x>-6. Dividing by -3 reverses the inequality: x<2.'],
    ['The solution of (x-1)/(x+2)≥0 is:', ['[-2,1]','(-∞,-2)∪[1,∞)','(-∞,-2]∪(1,∞)','[-2,∞)'], 1, 'Critical points are -2 (excluded) and 1 (included). Sign testing gives positive outside the interval between them.']);
  add('mathematics/algebra/permutations', 'Use permutations when order matters and combinations when it does not. Account for repeated objects before counting arrangements. Conditional restrictions are often easiest by complement counting, but the sample space and allowed repetition must be specified.',
    ['A committee of 3 is selected from 8 people. Number of possible committees is:', ['24','56','168','336'], 1, 'Order does not matter: C(8,3)=8×7×6/(3×2×1)=56.'],
    ['How many distinct arrangements of the letters in BANANA are possible?', ['20','60','120','720'], 1, 'There are 6 letters with A repeated 3 times and N twice. Count=6!/(3!2!)=60.']);
  add('mathematics/algebra/binomial', 'In (a+b)^n, term r+1 uses C(n,r)a^(n-r)b^r. Track exponents before calculating coefficients. A constant term requires the total power of x to vanish; the required r must also be an integer within the expansion range.',
    ['Coefficient of x³ in (1+2x)⁵ is:', ['40','60','80','160'], 2, 'Choose three factors 2x: C(5,3)×2³=10×8=80.'],
    ['The constant term in (x²+1/x)⁶ is:', ['6','15','20','30'], 1, 'General exponent is 2(6-r)-r=12-3r. Setting it to zero gives r=4; coefficient C(6,4)=15.']);
  add('mathematics/algebra/sequences', 'Identify an arithmetic or geometric structure before using a sum formula. An infinite geometric series converges only when |r|<1. A harmonic progression is defined through reciprocals forming an arithmetic progression; its terms cannot be summed using the AP sum formula directly.',
    ['An AP has first term 3 and common difference 4. Sum of its first 10 terms is:', ['180','200','210','240'], 2, 'S_n=n[2a+(n-1)d]/2=10[6+36]/2=210.'],
    ['An infinite GP has sum 12 and common ratio 1/3. Sum of the squares of all its terms is:', ['64','72','96','144'], 1, 'First term a=12(1-1/3)=8. Squared terms form a GP with first term 64 and ratio 1/9. Sum=64/(1-1/9)=72.']);
  add('mathematics/algebra/matrices', 'Matrix multiplication generally does not commute. A square matrix is invertible exactly when its determinant is nonzero. For an n×n matrix, multiplying every entry by k multiplies its determinant by k^n, not merely by k.',
    ['The determinant of [[2,3],[1,4]] is:', ['2','5','8','11'], 1, 'For a 2×2 matrix det=ad-bc=2×4-3×1=5.'],
    ['A is a 3×3 matrix with det(A)=2. Then det(2A⁻¹) equals:', ['1','2','4','8'], 2, 'det(A⁻¹)=1/2. Scaling a 3×3 matrix by 2 multiplies its determinant by 2³. Hence det(2A⁻¹)=8/2=4.']);
  add('mathematics/trigonometry/identities', 'Keep radians and degrees distinct. Use identities only on the domain where both sides exist. In solving trigonometric equations preserve all periodic branches; dividing by a trig expression can lose solutions when that expression is zero.',
    ['If θ is acute and sinθ=3/5, tanθ equals:', ['3/4','4/3','3/5','4/5'], 0, 'cosθ=√(1-9/25)=4/5, positive for acute θ. tanθ=(3/5)/(4/5)=3/4.'],
    ['How many solutions of sin(2x)=sin(x) lie in 0≤x<2pi?', ['2','3','4','5'], 2, 'sin x(2cos x-1)=0. Solutions are x=0, pi, pi/3 and 5pi/3. The endpoint 2pi is excluded.']);
  add('mathematics/trigonometry/inverse', 'Inverse trigonometric functions return principal values in restricted ranges. The expression arcsin(sin x) is not globally equal to x. Check both domain and principal branch before combining inverse functions using angle-sum identities.',
    ['The principal value of arcsin(sin(5pi/6)) is:', ['5pi/6','pi/6','-pi/6','-5pi/6'], 1, 'sin(5pi/6)=1/2 and arcsin returns a value in [-pi/2,pi/2], giving pi/6.'],
    ['The principal value arctan(1/2)+arctan(1/3) is:', ['pi/6','pi/4','pi/3','pi/2'], 1, 'tan(A+B)=[1/2+1/3]/[1-1/6]=1. Both angles are positive and the sum lies below pi/2, so it is pi/4.']);
  add('mathematics/geometry/lines', 'A line’s normal-vector form makes point-line distance and parallelism easy to inspect. Slope formulas exclude vertical lines unless handled separately. For angle bisectors, normalise each line equation by the length of its normal before equating signed distances.',
    ['Distance from (1,2) to the line 3x+4y-6=0 is:', ['1','2','3','5'], 0, 'Distance=|3(1)+4(2)-6|/√(3²+4²)=5/5=1.'],
    ['The acute angle between lines y=2x+1 and y=x/3-4 has tangent:', ['1/5','1','5/3','3'], 1, 'tanθ=|(m₁-m₂)/(1+m₁m₂)|=|(2-1/3)/(1+2/3)|=1. Thus θ=45°.']);
  add('mathematics/geometry/conics', 'Complete the square to identify the centre and radius of a circle. For an ellipse, c²=a²-b²; for a hyperbola, c²=a²+b². A parabola has eccentricity one and its focus-directrix definition is useful for deriving its standard equation.',
    ['For x²/25+y²/9=1, eccentricity is:', ['3/5','4/5','5/4','1'], 1, 'a=5,b=3, so c=√(25-9)=4 and e=c/a=4/5.'],
    ['For y²=12x, the focus and directrix are:', ['(3,0) and x=-3','(0,3) and y=-3','(6,0) and x=-6','(0,6) and y=-6'], 0, 'Compare y²=4ax: 4a=12, so a=3. Focus=(a,0); directrix x=-a.']);

  // Twenty new MAT items supplement, rather than replace, the existing pool.
  const mat = [
    ['Find the next term: 3, 8, 15, 24, 35, ...', ['46','48','49','50'],1,'Successive differences are 5,7,9,11; next difference is 13, giving 48.'],
    ['Find the next term: 2, 6, 18, 54, ...', ['108','144','162','216'],2,'Each term is multiplied by 3. The next is 54×3=162.'],
    ['A person faces north, turns 90° clockwise, then 180° anticlockwise. Final direction is:', ['North','East','South','West'],3,'North→east after the first turn; east→west after a half-turn anticlockwise.'],
    ['A walker travels 6 km east then 8 km north. Straight-line distance from the starting point is:', ['2 km','10 km','12 km','14 km'],1,'The legs are perpendicular. Displacement magnitude=√(6²+8²)=10 km.'],
    ['All surgeons are doctors. Some doctors are writers. Which conclusion must follow?', ['All surgeons are writers','Some writers are surgeons','All surgeons are doctors','No writers are doctors'],2,'Only the stated inclusion is guaranteed. The overlap of doctors and writers need not include any surgeon.'],
    ['No reptiles are mammals. All snakes are reptiles. Which conclusion follows?', ['All snakes are mammals','No snakes are mammals','Some mammals are snakes','No reptiles are snakes'],1,'Every snake lies in the reptile set, which is disjoint from mammals.'],
    ['If each letter is replaced by the next alphabet letter, how is CEE encoded?', ['DFF','BDD','DFE','EFF'],0,'C→D and each E→F, giving DFF.'],
    ['If A=1, B=2, ..., Z=26, the sum of letter values in NEPAL is:', ['46','48','50','52'],1,'N+E+P+A+L=14+5+16+1+12=48.'],
    ['A is taller than B; C is taller than A; D is shorter than B. Who is tallest?', ['A','B','C','D'],2,'The ordering is C>A>B>D, so C is tallest.'],
    ['In a row of 35, a student is 12th from the left. Position from the right is:', ['22nd','23rd','24th','25th'],2,'Position from right=N-left+1=35-12+1=24.'],
    ['A clock shows 3:30. The smaller angle between the hands is:', ['60°','75°','90°','105°'],1,'Minute hand=180°; hour hand=3×30+30×0.5=105°. Difference=75°.'],
    ['A fair six-sided die is rolled once. Probability of a prime result is:', ['1/3','1/2','2/3','5/6'],1,'Primes among 1–6 are 2,3,5: three of six equally likely outcomes, giving 1/2.'],
    ['Two fair coins are tossed. Probability of exactly one head is:', ['1/4','1/2','3/4','1'],1,'Equally likely outcomes HH,HT,TH,TT contain two with exactly one head. Probability=2/4.'],
    ['A can finish a task in 12 days and B in 18 days. At constant independent rates, together they need:', ['6 days','7.2 days','9 days','15 days'],1,'Combined daily rate=1/12+1/18=5/36. Time=36/5=7.2 days.'],
    ['A price rises by 20% and then falls by 20%. Net change from the original is:', ['No change','4% decrease','4% increase','8% decrease'],1,'Final multiplier=1.20×0.80=0.96: a 4% decrease.'],
    ['The average of five numbers is 18. Replacing 10 by 25 gives a new average of:', ['19','20','21','23'],2,'Original total=90. New total=90-10+25=105; mean=105/5=21.'],
    ['Choose the odd one out by number type: 16, 25, 36, 49, 63.', ['16','25','49','63'],3,'16,25,36,49 are perfect squares. 63 is not.'],
    ['Find the missing term: AZ, BY, CX, ...', ['DW','DV','EW','DX'],0,'First letters increase A,B,C,D while second letters decrease Z,Y,X,W.'],
    ['If yesterday was Wednesday, what day will it be 10 days after today?', ['Saturday','Sunday','Monday','Tuesday'],1,'Today is Thursday. Ten days ahead is three days ahead modulo seven: Sunday.'],
    ['A bag has 3 red and 2 blue balls. Two are drawn without replacement. Probability both are red is:', ['1/5','3/10','2/5','3/5'],1,'P(RR)=(3/5)(2/4)=6/20=3/10.']
  ];
  mat.forEach(([question,options,correct,explanation],i) => window.EDUPEAK_QUESTION_BANK.mentalAgility.push({
    id:'CF26-MAT-'+(i+1),subject:'Mental Agility',chapter:'Mental Agility',difficulty:i%2?'H':'M',question,options,correct,explanation,
    provenance:'Original CEE-style practice; not a verified past-paper question'
  }));
})();
